#!/usr/bin/env python3
from __future__ import annotations
import argparse, base64, zlib
from pathlib import Path

FILES = ['app/src/main/assets/shaders/motionv2/highlight_chroma_reliability.glsl', 'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2HighlightChromaReliability.java', 'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2MgcSourceExposure.java', 'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/PostPipeline.java', 'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/HdrxProcessor.java', 'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/PhotonMotionMgc1271Bridge.kt', 'app/src/main/java/com/particlesdevs/photoncamera/processing/render/Parameters.java', 'app/src/main/java/com/particlesdevs/photoncamera/processing/ultrahdr/MotionV2Jpeg444Encoder.java']
PAYLOAD_ZLIB_B64 = {
    'app/src/main/assets/shaders/motionv2/highlight_chroma_reliability.glsl': '',
    'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2HighlightChromaReliability.java': '',
    'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2MgcSourceExposure.java': '',
    'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/PostPipeline.java': '',
    'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/HdrxProcessor.java': '',
    'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/PhotonMotionMgc1271Bridge.kt': '',
    'app/src/main/java/com/particlesdevs/photoncamera/processing/render/Parameters.java': '',
    'app/src/main/java/com/particlesdevs/photoncamera/processing/ultrahdr/MotionV2Jpeg444Encoder.java': '',
}

def fail(m): raise SystemExit("FAIL: "+m)
def req(c,m):
    if not c: fail(m)

def payload_bytes(rel):
    try: return zlib.decompress(base64.b64decode(PAYLOAD_ZLIB_B64[rel]))
    except Exception as e: fail(f"embedded payload decode failed {rel}: {e}")

def main():
    ap=argparse.ArgumentParser(); ap.add_argument("root",nargs="?"); ap.add_argument("--self-test",action="store_true"); a=ap.parse_args()
    req(len(FILES)==len(set(FILES))==8,"runtime allowlist must contain exactly 8 unique files")
    req(sorted(PAYLOAD_ZLIB_B64)==sorted(FILES),"embedded payload allowlist mismatch")
    for rel in FILES: req(len(payload_bytes(rel))>0,"empty embedded payload "+rel)
    if a.self_test:
        print("PASS: 26535 embedded 8-file transform self-test"); return
    req(a.root is not None,"candidate root required")
    root=Path(a.root)
    req((root/"app/src/main").is_dir(),"candidate missing app/src/main")
    vp=root/"app/version.properties"; req(vp.is_file(),"base version.properties missing")
    vs=vp.read_text(); req("VERSION_NAME=0.9726534" in vs and "VERSION_BUILD=26534" in vs, "transform requires exact successful 26534 preversion base")
    for rel in FILES:
        dst=root/rel
        if rel not in FILES[:2]: req(dst.is_file(),"expected existing base file missing "+rel)
        dst.parent.mkdir(parents=True,exist_ok=True)
        dst.write_bytes(payload_bytes(rel))
    h=(root/"app/src/main/java/com/particlesdevs/photoncamera/processing/processor/HdrxProcessor.java").read_text()
    req("IRIS_26535_NIGHT_SHARED_SPATIAL_RGB_SOLE_OWNER" in h,"Night shared RGB marker absent after transform")
    print("PASS: 26535 exact embedded 8-file runtime transform applied")

if __name__=="__main__": main()
